from pathlib import Path
import sys,json,subprocess,concurrent.futures,re,html,shutil
ROOT=Path(__file__).resolve().parents[2];sys.path.insert(0,str(ROOT/'scripts/video'))
from build_embrace_future_illustrations import OUT,SOURCES,FF,paths
items=[('rise-of-agents','Rise of Agents','Review it. Make it better.','The student reviews a basketball reel, then changes “Friday highlights” to “30 points on Friday.” The caption is emphasized on “reviewing” and updated on “making it better.”',2),('data-centers','Data Centers','A recognizable physical facility.','A realistic illustrative exterior replaces the power-station-like drawing. A restrained push keeps the short shot readable; the following chat diagram remains.',0),('work-changes','Work Changes','Build the expertise yourself.','The same learner makes an attempt, spots a distribution error, and revises the working. A magnified notebook excerpt makes the change readable while the narration emphasizes learning.',2)]
def stamp(f):return f'{f//1800}:{f/30%60:05.2f}'
def clip(job):
 pid,variant,src,start,duration=job;dest=OUT/f'clips/{pid}-{variant}.mp4'
 if not dest.exists():subprocess.run([FF,'-v','error','-ss',str(start),'-i',str(src),'-t',str(duration),'-c:v','libx264','-preset','veryfast','-crf','18','-c:a','aac','-b:a','128k','-movflags','+faststart',str(dest)],check=True)
jobs=[];sections=[]
old=ROOT/'video-audit/embrace-the-future-illustration-opportunities-2026-10-08'
proposals=json.loads((old/'opportunities.json').read_text())['opportunities']
for slug,title,heading,desc,state in items:
 cfg=SOURCES[slug];pid=cfg['id'];src,dst=paths(slug,cfg)
 for variant,p in [('before',src),('after',dst)]:jobs.append((pid,variant,p,cfg['start']/30-3,(cfg['end']-cfg['start'])/30+6))
 p=next(x for x in proposals if x['id']==pid);shutil.copy2(old/p['image'],OUT/f'previews/{pid}-before.jpg')
 players=''.join(f'<div><h3>{label}</h3><video aria-label="{title} {variant} excerpt" controls playsinline preload="none" poster="previews/{pid}-{poster}.jpg" src="clips/{pid}-{variant}.mp4"></video><p class="small"><a href="clips/{pid}-{variant}.mp4">Open {variant} excerpt separately</a></p></div>' for variant,label,poster in [('before','Previous version','before'),('after','Updated version',f'state-{state}')])
 states=' · '.join(f'<a href="previews/{pid}-state-{i}.jpg">State {i+1}</a>' for i in range(len(cfg['changes'])+1))
 sections.append(f'<section id="{pid}"><p class="eyebrow">{title} · {stamp(cfg["start"])}–{stamp(cfg["end"])}</p><h2>{heading}</h2><p>{desc}</p><div class="comparison">{players}</div><p class="small">Both excerpts include three seconds before and after the changed shot. Player time begins at the start of the excerpt.</p><p><a href="../../Prompts/{slug}-v{cfg["version"]}.mp4">Full candidate · {title} v{cfg["version"]}</a> · {states} · <a href="{slug}-manifest.json">Edit record</a></p></section>')
with concurrent.futures.ThreadPoolExecutor(max_workers=3) as ex:list(ex.map(clip,jobs))
checks=[json.loads((OUT/slug/'qa.json').read_text()) for slug,_,_,_,_ in items]
(OUT/'verification.json').write_text(json.dumps(checks,indent=2)+'\n')
qa=''.join(f'<li>{r["slug"]}: {r["frames"]:,} decoded frames; {r["duration"]:.2f} seconds; original AAC packets, timestamps and decoded audio are identical.</li>' for r in checks)
style='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f5f5f9;color:#242632;font:17px/1.6 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}main{max-width:1240px;margin:auto;padding:52px 30px}h1{font-size:44px;line-height:1.15;max-width:950px}h2{font-size:28px;line-height:1.25}h3{font-size:18px;margin:16px 0 10px}.eyebrow{font-size:13px;letter-spacing:.09em;text-transform:uppercase;color:#625286;font-weight:650}nav{display:flex;gap:22px;flex-wrap:wrap;margin:28px 0}a{color:#524270;text-underline-offset:3px}section{padding:28px;background:white;border:1px solid #dad8e2;border-radius:16px;margin:28px 0;scroll-margin-top:20px}.comparison{display:grid;grid-template-columns:1fr 1fr;gap:24px}video{display:block;width:100%;aspect-ratio:16/9;background:#111;border-radius:8px}.small{font-size:14px;color:#5b5c68}.note{border-left:4px solid #735d98;padding:12px 18px;background:#eae7f0}.gallery{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.gallery img{width:100%}footer{font-size:14px;color:#646370;padding:24px 0}@media(max-width:800px){main{padding:24px 16px}h1{font-size:34px}.comparison,.gallery{grid-template-columns:1fr}section{padding:20px}}'''
body=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Embrace the Future — Illustration Updates</title><style>{style}</style></head><body><main><p class="eyebrow">Learning Illustration Pass · October 8, 2026</p><h1>Show the judgment. Show the learning.</h1><p>Three finished illustration updates in the established photographic style. The new scenes make reviewing, understanding the infrastructure, and building expertise visible.</p><div class="note"><strong>Approved and shipped locally.</strong> Rise of Agents v8, Data Centers v6 and Work Changes v6 are installed. Commit d243b5ef; queued for batch deployment. Narration and runtime are retained. <a href="local-install.json">Local release record</a>.</div><nav><a href="#P1">Improve the reel</a><a href="#P2">See the facility</a><a href="#P3">Build expertise</a><a href="#checks">Checks and source assets</a></nav>{''.join(sections)}<section id="checks"><h2>Verification and scope</h2><ul>{qa}</ul><p>All 681 changed frames were compared with their intended render. Eleven transition boundaries were checked, including state changes and the return to copied source video. Encoded states and boundary strips are retained for inspection.</p><p>Untouched video packets are copied. All frames outside the small reencoded groups are pixel-identical. Rise of Agents also reencodes 236 unchanged board frames in the same group as the new shot; their minimum measured PSNR is 64.03 dB. The original board, framing and timing remain. Work Changes and Data Centers reencode only their replacement shots.</p><p>All source audio packets and timestamps are unchanged, with matching decoded audio hashes. Technical checks do not substitute for listening: continuous audible review by the agent has not been completed. Use the excerpts with sound to assess pacing. The course now uses the approved videos locally. Canonical boards and lesson files are unchanged.</p><p><a href="verification.json">Verification data</a> · <a href="REVIEW.md">Build record</a> · <a href="../embrace-the-future-illustration-opportunities-2026-10-08/review.html">Approved proposals</a> · <a href="../../scripts/video/LEARNING-ILLUSTRATION-PASS.md">Style and process</a></p><h2>Reusable scene assets</h2><p>Created with the built-in image-generation tool. Screen content, caption emphasis and the notebook working were rendered separately. The same student, room and objects carry through each sequence.</p><div class="gallery">{''.join(f'<a href="assets/{name}.png"><img src="assets/{name}.png" loading="lazy" alt="{label}"><span>{label}</span></a>' for name,label in [('agents','Basketball review scene'),('facility','Data-center exterior'),('study','Student checking their work')])}</div><p><a href="assets/prompts.json">Complete prompts and image provenance</a> · <a href="assets/basketball.png">Basketball clip image</a> · <a href="assets/study_before.png">Matched first-attempt scene</a></p></section><footer>Three supporting shots, 22.70 seconds total. Six other Embrace the Future videos retain their existing illustrations. Approved locally; publication awaits the next batch deployment.</footer></main></body></html>'''
(OUT/'review.html').write_text(body)
missing=[p for p in re.findall(r'(?:src|href)="([^"#]+)"',body) if p!='REVIEW.md' and not (OUT/p).exists()];assert not missing,missing
print(OUT/'review.html')
